+    let cx = VerifyContext {
+        region: &wall,
+        model: Some(&facets),
+        tool: &ball,
+        mode,
+        stock_top_z: 0.0,
+        clearance_z: 20.0,
+        gouge_tol: TOL,
+        z_tol: 1e-6,
+        finish_tol: Some(finish_tol),
+        model_excess: excess,
+        ..Default::default()
+    };
+    verify(path, &cx).iter().find_map(|w| match w {
+        Warning::Envelope { gouge_mm, .. } => Some(*gouge_mm),
+        _ => None,
+    })
+}
